setup_files.main.tf:
terraform {
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = "us-east-1"
}

resource "aws_kms_key" "data_encryption" {
  description             = "Encrypts production data at rest"
  deletion_window_in_days = 30
  enable_key_rotation     = true
}

